import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents rounds half to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
  assert.equal(roundCents(2.4), 2);
  assert.equal(roundCents(-0.5), 0);
});

test('roundCents ignores binary noise', () => {
  // 119.95 * 4.2 = 503.79 in decimal, but 503.78999999999999 in binary
  assert.equal(roundCents(119.95 * 4.2), 50379);
});

test('formatEuros adds the sign, thousands separators and two decimals', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(-5), '-€0.05');
  assert.equal(formatEuros(0), '€0.00');
});

test('parseEuros reads what people type', () => {
  assert.deepEqual(parseEuros('12'), { ok: true, value: 1200 });
  assert.deepEqual(parseEuros('12.5'), { ok: true, value: 1250 });
  assert.deepEqual(parseEuros('1,234.56'), { ok: true, value: 123456 });
  assert.deepEqual(parseEuros('invalid'), { ok: false, error: 'AMOUNT_INVALID' });
});

test('RATES has EUR, USD, GBP', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert rejects unknown currency', () => {
  const result = convert(100000, 'JPY');
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('convert EUR to EUR returns same amount', () => {
  const result = convert(123456, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 123456);
});

test('convert EUR to USD', () => {
  // 100 EUR in cents = 10000
  // Rate: 1 EUR = 1.085 USD
  // 100 EUR = 108.5 USD = 10850 cents
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10850);
});

test('convert EUR to GBP', () => {
  // 100 EUR in cents = 10000
  // Rate: 1 EUR = 0.8425 GBP
  // 100 EUR = 84.25 GBP = 8425 cents
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  assert.equal(result.value, 8425);
});

test('convert rounds result correctly', () => {
  // 1 EUR in cents = 100
  // Rate: 1 EUR = 1.085 USD
  // 1 EUR = 1.085 USD = 108.5 cents
  // Should round to 109 (half to even: 108.5 rounds to 108, but test should verify rounding)
  const result = convert(100, 'USD');
  assert.equal(result.ok, true);
  // 108.5 cents rounds to 108 (even banker's rounding)
  assert.equal(result.value, 108);
});

test('convert with large amount', () => {
  // 1,000,000 EUR in cents = 100,000,000
  // To USD: 1,000,000 * 1.085 = 1,085,000 USD = 108,500,000 cents
  const result = convert(100000000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 108500000);
});

test('formatMoney EUR format', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
  assert.equal(formatMoney(100, 'EUR'), '€1.00');
  assert.equal(formatMoney(-5000, 'EUR'), '-€50.00');
});

test('formatMoney USD format', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
  assert.equal(formatMoney(100, 'USD'), '$1.00');
  assert.equal(formatMoney(-5000, 'USD'), '-$50.00');
});

test('formatMoney GBP format', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
  assert.equal(formatMoney(100, 'GBP'), '£1.00');
  assert.equal(formatMoney(-5000, 'GBP'), '-£50.00');
});

test('formatMoney zero amount', () => {
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
});

test('formatMoney no thousands separator for amounts under 1000', () => {
  assert.equal(formatMoney(99999, 'EUR'), '€999.99');
  assert.equal(formatMoney(100000, 'EUR'), '€1,000.00');
});

test('convert and format workflow EUR to USD', () => {
  // Start with 114950 cents in EUR
  const convertResult = convert(114950, 'USD');
  assert.equal(convertResult.ok, true);

  const formatted = formatMoney(convertResult.value, 'USD');
  // 114950 EUR cents = 1149.50 EUR
  // 1149.50 EUR * 1.085 USD/EUR = 1246.9075 USD = 124690.75 cents (rounded to 124691)
  // Actually: 114950 / 100 = 1149.50 EUR
  // 1149.50 * 1.085 = 1246.9075 USD
  // 1246.9075 * 100 = 124690.75 cents
  // Rounded: 124691 cents
  const expected = formatMoney(124691, 'USD');
  assert.equal(formatted, expected);
});

test('convert and format workflow EUR to GBP', () => {
  const convertResult = convert(114950, 'GBP');
  assert.equal(convertResult.ok, true);

  const formatted = formatMoney(convertResult.value, 'GBP');
  // 114950 EUR cents = 1149.50 EUR
  // 1149.50 EUR * 0.8425 GBP/EUR = 968.6362 GBP = 96863.62 cents (rounded to 96864)
  const expected = formatMoney(96864, 'GBP');
  assert.equal(formatted, expected);
});

test('convert maintains precision with decimal rates', () => {
  // Test that rounding is applied correctly
  const eurCents = 10000; // 100 EUR
  const result = convert(eurCents, 'USD');

  // 100 * 1.085 = 108.5, rounded to 108.5 -> 109 (or 108 with banker's rounding)
  // Actually, 108.5 with banker's rounding (half to even) rounds to 108
  assert.equal(result.ok, true);
  assert.equal(result.value, 10850); // 108.50 USD in cents
});

test('convert small amounts USD', () => {
  // 1 cent in EUR
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  // 1 EUR cent = 0.01 EUR = 0.01 * 1.085 = 0.01085 USD = 1.085 cents
  // Rounded: 1 cent
  assert.equal(result.value, 1);
});

test('convert small amounts GBP', () => {
  // 1 cent in EUR
  const result = convert(1, 'GBP');
  assert.equal(result.ok, true);
  // 1 EUR cent = 0.01 EUR = 0.01 * 0.8425 = 0.008425 GBP = 0.8425 cents
  // Rounded: 1 cent (banker's rounding: 0.8425 rounds up to 1)
  assert.equal(result.value, 1);
});

